package com.pricetrack.exchange.custody.proof;

import static com.pricetrack.exchange.custody.proof.CTokenTransactionProofModels.*;
import static com.pricetrack.exchange.custody.proof.CTransactionProofVerifierTest.*;
import static org.junit.jupiter.api.Assertions.*;
import com.pricetrack.exchange.custody.abi.*;
import com.pricetrack.exchange.custody.token.CTokenLedgerModels;
import java.math.BigInteger;
import java.util.*;
import org.junit.jupiter.api.Test;
import org.web3j.crypto.*;
import org.web3j.rlp.*;

/** Public tiny17/23/29 keys. Token-only results never contain or advance a Vault financial State. */
class CTokenTransactionProofVerifierTest {
    final CTransactionProofVerifierTest f=new CTransactionProofVerifierTest();final CTokenTransactionProofVerifier verifier=new CTokenTransactionProofVerifier();
    final CAbiCodec abi=new CAbiCodec();final CAbiEventCodec events=new CAbiEventCodec();
    Input transfer(long amount){return fixture(f.seed(2000).token(),new CAbiModels.Transfer(addr(RELAY),n(amount)),USER,null);}
    Input from(String owner,String to,long amount,ECKeyPair spender,BigInteger allowance){return fixture(f.seed(2000).token(),new CAbiModels.TransferFrom(owner,to,n(amount)),spender,allowance);}
    Input fixture(CTokenLedgerModels.State token,CAbiModels.Call call,ECKeyPair key,BigInteger allowance){
        CAbiEventModels.Event event;
        if(call instanceof CAbiModels.Transfer c)event=new CAbiEventModels.Transfer(addr(key),c.to(),c.amount());
        else if(call instanceof CAbiModels.Approve c)event=new CAbiEventModels.Approval(addr(key),c.spender(),c.amount());
        else{var c=(CAbiModels.TransferFrom)call;event=new CAbiEventModels.Transfer(c.from(),c.to(),c.amount());}
        byte[] raw=raw(abi.encode(call),key);String hash=hex(Hash.sha3(raw));BigInteger index=token.lastTransactionIndex().add(n(1));var encoded=events.encode(TOKEN,event);
        var log=new CReceiptEnvelopeModels.RawLog(hash,n(1),h(101),index,index.multiply(n(10)),false,TOKEN,encoded.topics(),encoded.data());
        var receipt=new CReceiptEnvelopeModels.Receipt(hash,n(1),h(101),index,addr(key),TOKEN,1,List.of(log));
        var e=new CReceiptEnvelopeModels.Input(hex(raw),hash,new CReceiptEnvelopeModels.Deployment(n(31337),TOKEN,VAULT,CONTROLLER,RULES),new CReceiptEnvelopeModels.BlockContext(n(1),h(101),n(1000)),receipt);
        var point=new CAuthorizationModels.ObservationPoint(n(1),h(101),hash,index);String owner=call instanceof CAbiModels.TransferFrom from?from.from():addr(key);
        return new Input(e,new Context(point,token,h(100),allowance==null?null:new AllowanceObservation(point,owner,addr(key),allowance)));
    }
    byte[] raw(String data,ECKeyPair key){List<RlpType> v=new ArrayList<>(List.of(r(n(7)),r(n(1)),r(n(1_000_000)),RlpString.create(bytes(TOKEN)),r(n(0)),RlpString.create(bytes(data))));var unsigned=new ArrayList<>(v);unsigned.addAll(List.of(r(n(31337)),r(n(0)),r(n(0))));var s=Sign.signMessage(Hash.sha3(RlpEncoder.encode(new RlpList(unsigned))),key,false);v.add(r(n(31337*2L+35+s.getV()[0]-27)));v.add(r(new BigInteger(1,s.getR())));v.add(r(new BigInteger(1,s.getS())));return RlpEncoder.encode(new RlpList(v));}
    Result ok(Input i){var r=verifier.verify(i);assertEquals(Decision.VERIFIED_IN_SCOPE,r.decision(),r.reason());return r;}
    void deny(Input i){var r=verifier.verify(i);assertNotEquals(Decision.VERIFIED_IN_SCOPE,r.decision());assertNull(r.verified());}
    Input context(Input i,String field,Object value){return change(i,"context",change(i.context(),field,value));}
    Input logs(Input i,List<CReceiptEnvelopeModels.RawLog> logs){return change(i,"envelope",change(i.envelope(),"receipt",change(i.envelope().receipt(),"logs",logs)));}
    Input event(Input i,CAbiEventModels.Event event){var list=new ArrayList<>(i.envelope().receipt().logs());var encoded=events.encode(TOKEN,event);list.set(0,change(change(list.getFirst(),"topics",encoded.topics()),"data",encoded.data()));return logs(i,list);}
    @Test void ownerTransferMovesOnlyWalletTokensAndKeepsVaultAssets(){Input i=transfer(100);var r=ok(i);assertEquals(i.context().token().balanceOf(OWNER).subtract(n(100)),r.verified().token().balanceOf(OWNER));assertEquals(n(100),r.verified().token().balanceOf(addr(RELAY)));assertEquals(n(5000),r.verified().token().balanceOf(VAULT));assertEquals(VaultAssetEffect.ZERO_DELTA,r.verified().vaultAssetEffect());}
    @Test void zeroTransferFromUnfundedWalletIsObserved(){Input i=fixture(f.seed(2000).token(),new CAbiModels.Transfer(OWNER,n(0)),ORACLE,null);var r=ok(i);assertEquals(n(0),r.verified().token().balanceOf(addr(ORACLE)));assertEquals(4,r.verified().token().observations().size());}
    @Test void fundedSelfTransferRequiresBalanceAndPreservesItExactly(){Input i=fixture(f.seed(2000).token(),new CAbiModels.Transfer(OWNER,n(100)),USER,null);var r=ok(i);assertEquals(i.context().token().balances(),r.verified().token().balances());deny(fixture(f.seed(2000).token(),new CAbiModels.Transfer(addr(ORACLE),n(1)),ORACLE,null));}
    @Test void approveAndZeroApprovalNeverProveCurrentAllowance(){for(BigInteger value:List.of(n(0),n(100),CAbiModels.UINT_MAX)){Input i=fixture(f.seed(2000).token(),new CAbiModels.Approve(VAULT,value),USER,null);var r=ok(i);assertEquals(i.context().token().balances(),r.verified().token().balances());assertEquals(value,r.verified().token().lastObservedApprovals().get(new CTokenLedgerModels.ApprovalKey(OWNER,VAULT)).observedValue());assertFalse(r.currentAllowanceVerified());}}
    @Test void transferFromUsesActualRawSpenderAndExplicitAllowance(){Input i=from(OWNER,addr(RELAY),100,ORACLE,n(100));var r=ok(i);assertEquals(n(100),r.verified().token().balanceOf(addr(RELAY)));assertTrue(r.verified().token().lastObservedApprovals().isEmpty());}
    @Test void transferFromOwnerEqualsCallerStillRequiresAllowance(){Input i=from(OWNER,addr(RELAY),100,USER,null);assertEquals(Decision.INSUFFICIENT,verifier.verify(i).decision());ok(context(i,"allowance",new AllowanceObservation(i.context().point(),OWNER,OWNER,n(100))));}
    @Test void zeroTransferFromStillRequiresExplicitZeroAllowance(){Input i=from(addr(ORACLE),OWNER,0,USER,null);assertEquals(Decision.INSUFFICIENT,verifier.verify(i).decision());ok(context(i,"allowance",new AllowanceObservation(i.context().point(),addr(ORACLE),OWNER,n(0))));}
    @Test void insufficientFiniteAllowanceFailsAndMaxIsSupported(){Input i=from(OWNER,addr(RELAY),100,ORACLE,n(99));assertEquals("C_TTX_ALLOWANCE_AMOUNT",verifier.verify(i).reason());ok(context(i,"allowance",change(i.context().allowance(),"value",CAbiModels.UINT_MAX)));}
    @Test void allowanceMustHaveAllFieldsAndExactPointOwnerSpender(){Input i=from(OWNER,addr(RELAY),100,ORACLE,n(100));for(String field:List.of("point","owner","spender","value"))assertEquals(Decision.INSUFFICIENT,verifier.verify(context(i,"allowance",change(i.context().allowance(),field,null))).decision());for(String field:List.of("owner","spender"))assertEquals(Decision.INSUFFICIENT,verifier.verify(context(i,"allowance",change(i.context().allowance(),field,addr(RELAY)))).decision());deny(context(i,"allowance",change(i.context().allowance(),"point",change(i.context().point(),"transactionHash",h(99)))));}
    @Test void negativeOrOverflowAllowanceCannotBeAccepted(){Input i=from(OWNER,addr(RELAY),100,ORACLE,n(100));deny(context(i,"allowance",change(i.context().allowance(),"value",n(-1))));deny(context(i,"allowance",change(i.context().allowance(),"value",CAbiModels.UINT_MAX.add(n(1)))));}
    @Test void transferFromDoesNotConsumeOrInventApprovalObservation(){var token=f.seed(2000).token();var approval=new CTokenLedgerModels.Transaction(token.deployment(),TB,h(700),n(3),CTokenLedgerModels.Outcome.SUCCESS,List.of(new CTokenLedgerModels.Log(n(30),TOKEN,new CAbiEventModels.Approval(OWNER,addr(ORACLE),n(200)))));token=f.tokens.apply(token,approval);Input i=fixture(token,new CAbiModels.TransferFrom(OWNER,addr(RELAY),n(100)),ORACLE,n(200));var r=ok(i);assertEquals(token.lastObservedApprovals(),r.verified().token().lastObservedApprovals());assertEquals(n(200),r.verified().token().lastObservedApprovals().get(new CTokenLedgerModels.ApprovalKey(OWNER,addr(ORACLE))).observedValue());assertFalse(r.currentAllowanceVerified());}
    @Test void zeroReceiverAndZeroSpenderAreRejectedEvenForZeroValue(){deny(fixture(f.seed(2000).token(),new CAbiModels.Transfer(ZERO,n(0)),USER,null));deny(fixture(f.seed(2000).token(),new CAbiModels.Approve(ZERO,n(0)),USER,null));deny(from(OWNER,ZERO,0,USER,n(0)));deny(from(ZERO,OWNER,0,USER,n(0)));}
    @Test void selfTransferFromAlsoRequiresEnoughBalance(){deny(from(addr(ORACLE),addr(ORACLE),1,USER,n(1)));ok(from(addr(ORACLE),addr(ORACLE),0,USER,n(0)));}
    @Test void positiveDirectVaultInflowIsUnsupportedWithNoReturnedState(){var r=verifier.verify(fixture(f.seed(2000).token(),new CAbiModels.Transfer(VAULT,n(1)),USER,null));assertEquals(Decision.UNSUPPORTED,r.decision());assertEquals("C_TTX_VAULT_ASSET_DELTA",r.reason());assertNull(r.verified());}
    @Test void positiveTransferFromVaultInflowOutflowAndSelfAreAllUnsupported(){for(var endpoints:List.of(List.of(OWNER,VAULT),List.of(VAULT,OWNER),List.of(VAULT,VAULT))){var r=verifier.verify(from(endpoints.get(0),endpoints.get(1),1,USER,CAbiModels.UINT_MAX));assertEquals(Decision.UNSUPPORTED,r.decision());assertNull(r.verified());}}
    @Test void zeroVaultInflowOutflowAndSelfRemainExplicitZeroDeltaEvents(){ok(fixture(f.seed(2000).token(),new CAbiModels.Transfer(VAULT,n(0)),USER,null));for(var endpoints:List.of(List.of(OWNER,VAULT),List.of(VAULT,OWNER),List.of(VAULT,VAULT)))assertEquals(VaultAssetEffect.ZERO_DELTA,ok(from(endpoints.get(0),endpoints.get(1),0,USER,n(0))).verified().vaultAssetEffect());}
    @Test void everyTransferEventFieldMustMatchRawCalldataAndSender(){Input i=transfer(100);deny(event(i,new CAbiEventModels.Transfer(addr(ORACLE),addr(RELAY),n(100))));deny(event(i,new CAbiEventModels.Transfer(OWNER,addr(ORACLE),n(100))));deny(event(i,new CAbiEventModels.Transfer(OWNER,addr(RELAY),n(101))));}
    @Test void approveOwnerSpenderAndValueMustMatchOriginalRaw(){Input i=fixture(f.seed(2000).token(),new CAbiModels.Approve(VAULT,n(100)),USER,null);deny(event(i,new CAbiEventModels.Approval(addr(ORACLE),VAULT,n(100))));deny(event(i,new CAbiEventModels.Approval(OWNER,addr(RELAY),n(100))));deny(event(i,new CAbiEventModels.Approval(OWNER,VAULT,n(101))));}
    @Test void extraApprovalIsNotAnOZAllowanceSpendEvent(){Input i=from(OWNER,addr(RELAY),100,ORACLE,n(100));var list=new ArrayList<>(i.envelope().receipt().logs());var old=list.getFirst();var approval=events.encode(TOKEN,new CAbiEventModels.Approval(OWNER,addr(ORACLE),n(0)));list.add(change(change(change(old,"logIndex",old.logIndex().add(n(1))),"topics",approval.topics()),"data",approval.data()));assertEquals("C_TTX_EVENT_COUNT",verifier.verify(logs(i,list)).reason());}
    @Test void mintBurnOrUnexpectedKnownEventCannotReplaceExpectedTransfer(){Input i=transfer(100);deny(event(i,new CAbiEventModels.Transfer(ZERO,OWNER,n(100))));deny(event(i,new CAbiEventModels.Transfer(OWNER,ZERO,n(100))));deny(event(i,new CAbiEventModels.Approval(OWNER,VAULT,n(100))));}
    @Test void exactEmitterAndSingleEventAreRequired(){Input i=transfer(100);deny(logs(i,List.of()));deny(logs(i,List.of(change(i.envelope().receipt().logs().getFirst(),"emitter",VAULT))));}
    @Test void receiptHashAndRawSenderCannotBeChangedWithoutActualSignature(){Input i=transfer(100);deny(change(i,"envelope",change(i.envelope(),"expectedTransactionHash",h(99))));deny(change(i,"envelope",change(i.envelope(),"receipt",change(i.envelope().receipt(),"from",addr(ORACLE)))));}
    @Test void prestatePointAndDeploymentTokenChainMustMatch(){Input i=transfer(100);deny(context(i,"point",change(i.context().point(),"transactionIndex",n(99))));deny(change(i,"envelope",change(i.envelope(),"deployment",change(i.envelope().deployment(),"chainId",n(31338)))));deny(context(i,"token",change(i.context().token(),"deployment",change(i.context().token().deployment(),"token",a(99)))));}
    @Test void headerAncestryAndCursorOrderAreNotSkipped(){Input i=transfer(100);deny(context(i,"parentBlockHash",h(999)));deny(context(i,"token",change(i.context().token(),"lastTransactionIndex",n(4))));}
    @Test void missingContextOrInitialMintEvidenceIsInsufficient(){Input i=transfer(100);for(String field:List.of("point","token","parentBlockHash"))assertEquals(Decision.INSUFFICIENT,verifier.verify(context(i,field,null)).decision());var initial=f.tokens.initial(TD,new CTokenLedgerModels.Block(n(0),h(100),h(0)));assertEquals(Decision.INSUFFICIENT,verifier.verify(context(i,"token",initial)).decision());}
    @Test void forgedTokenBalancesWithSameSupplyCannotPass(){Input i=transfer(100);var balances=new HashMap<>(i.context().token().balances());balances.put(OWNER,balances.get(OWNER).subtract(n(1)));balances.put(a(88),n(1));deny(context(i,"token",change(i.context().token(),"balances",balances)));}
    @Test void revertedTransferFromHasNoAllowanceOrAuthorizationConclusion(){Input i=from(OWNER,VAULT,100,USER,null);i=logs(i,List.of());i=change(i,"envelope",change(i.envelope(),"receipt",change(i.envelope().receipt(),"status",0)));var r=ok(i);assertTrue(r.verified().reverted());assertEquals(i.context().token().balances(),r.verified().token().balances());assertFalse(r.currentAllowanceVerified());}
    @Test void revertedCallCannotClaimLogsAndUnsupportedCallIsNotFaked(){Input i=transfer(100);deny(change(i,"envelope",change(i.envelope(),"receipt",change(i.envelope().receipt(),"status",0))));var unknown=f.envelope(new CAbiModels.Cancel(n(0)),false,3,List.of());assertEquals(Decision.UNSUPPORTED,verifier.verify(change(i,"envelope",unknown)).decision());}
    @Test void envelopeResourceCapsAndOutputRedactionRemainActive(){Input i=transfer(100);Input excessive=logs(i,Collections.nCopies(129,i.envelope().receipt().logs().getFirst()));assertEquals(Decision.INSUFFICIENT,verifier.verify(excessive).decision());var r=ok(i);assertFalse(i.toString().contains(i.envelope().rawSignedTransaction()));assertFalse(r.toString().contains(i.envelope().rawSignedTransaction()));}
    @Test void zeroDeltaIsBoundToTheNormalizedDeclaredVaultNotAnAuthenticatedDeployment(){Input i=transfer(100);var r=ok(change(i,"envelope",change(i.envelope(),"deployment",change(i.envelope().deployment(),"vault",upper(VAULT)))));assertEquals(VAULT,r.verified().declaredVault());assertTrue(r.verificationScope().contains("ZERO_DELTA binds declaredVault only"));var another=ok(change(i,"envelope",change(i.envelope(),"deployment",change(i.envelope().deployment(),"vault",a(99)))));assertEquals(a(99),another.verified().declaredVault());assertNotEquals(r.verified().declaredVault(),another.verified().declaredVault());}
    @Test void repeatedOriginalPrestateIsDeterministicButNoGlobalCursorIsClaimed(){Input i=transfer(100);var r=ok(i);assertEquals(r,ok(i));assertFalse(r.completeCoverage());assertFalse(r.globalCoverage());assertTrue(r.verificationScope().contains("PREVALIDATED_TOKEN_CONTEXT_ONLY"));assertEquals(n(2),i.context().token().lastTransactionIndex());assertEquals(n(3),r.verified().token().lastTransactionIndex());assertFalse(Arrays.stream(Verified.class.getRecordComponents()).anyMatch(field->field.getType().getSimpleName().equals("State")&&!field.getType().equals(CTokenLedgerModels.State.class)));}
}
